// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.POST(options.BaseURL+"/api/auth/login", wrapper.AuthLogin)
	router.POST(options.BaseURL+"/api/auth/logout", wrapper.AuthLogout)
	router.GET(options.BaseURL+"/api/auth/me", wrapper.AuthMe)
	router.POST(options.BaseURL+"/api/auth/forgot-password", wrapper.AuthForgotPassword)
	router.POST(options.BaseURL+"/api/auth/reset-password", wrapper.AuthResetPassword)
	router.POST(options.BaseURL+"/api/users", wrapper.UserCreate)
	router.GET(options.BaseURL+"/api/schools", wrapper.SchoolList)
	router.POST(options.BaseURL+"/api/schools", wrapper.SchoolCreate)
	router.PATCH(options.BaseURL+"/api/schools/:id", wrapper.SchoolUpdate)
	router.GET(options.BaseURL+"/api/schools/:id/admins", wrapper.SchoolAdminList)
	router.POST(options.BaseURL+"/api/schools/:id/admins", wrapper.SchoolAdminAdd)
	router.DELETE(options.BaseURL+"/api/schools/:id/admins/:uid", wrapper.SchoolAdminRemove)
	router.GET(options.BaseURL+"/api/accounts", wrapper.AccountList)
	router.POST(options.BaseURL+"/api/accounts", wrapper.AccountCreate)
	router.DELETE(options.BaseURL+"/api/accounts/:id", wrapper.AccountDelete)
	router.GET(options.BaseURL+"/api/accounts/:id", wrapper.AccountGet)
	router.PATCH(options.BaseURL+"/api/accounts/:id", wrapper.AccountUpdate)
	router.POST(options.BaseURL+"/api/accounts/:id/review", wrapper.AccountReview)
	router.POST(options.BaseURL+"/api/accounts/:id/pause", wrapper.AccountPause)
	router.POST(options.BaseURL+"/api/accounts/:id/verify", wrapper.AccountVerify)
	router.POST(options.BaseURL+"/api/accounts/:id/sign", wrapper.AccountSign)
	router.GET(options.BaseURL+"/api/schedule/windows", wrapper.ScheduleWindows)
	router.GET(options.BaseURL+"/api/schedule/preview", wrapper.SchedulePreview)
	router.POST(options.BaseURL+"/api/schedule/plan", wrapper.SchedulePlan)
	router.POST(options.BaseURL+"/api/schedule/override", wrapper.ScheduleOverride)
	router.GET(options.BaseURL+"/api/me/time-pref", wrapper.TimePrefGet)
	router.PUT(options.BaseURL+"/api/me/time-pref", wrapper.TimePrefSet)
	router.GET(options.BaseURL+"/api/capacity", wrapper.CapacityGet)
	router.GET(options.BaseURL+"/api/me/photos", wrapper.PhotoList)
	router.POST(options.BaseURL+"/api/me/photos", wrapper.PhotoUpload)
	router.DELETE(options.BaseURL+"/api/me/photos/:id", wrapper.PhotoDelete)
	router.GET(options.BaseURL+"/api/me/photos/:id", wrapper.PhotoGet)
	router.PUT(options.BaseURL+"/api/me/photo-retention", wrapper.PhotoRetentionSet)
	router.GET(options.BaseURL+"/healthz", wrapper.HealthCheck)
}
